import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def main():
    n, m = map(int, sys.stdin.readline().split())

    if m < n - 1 or m > n * (n - 1) // 2:
        print("Impossible")
        return

